def gen(rng):
    def fmt(rows, s, e):
        return f"{len(rows)} {len(rows[0])}\n{s[0]} {s[1]} {e[0]} {e[1]}\n" + '\n'.join(rows)
    tests = [
        fmt(['.'], (0, 0), (0, 0)), fmt(['#'], (0, 0), (0, 0)), fmt(['.#.'], (0, 0), (0, 2)),
        fmt(['.#..', '.#.#', '...#'], (0, 0), (2, 3)), fmt(['.##', '###', '##.'], (0, 0), (2, 2)),
        fmt(['..#'], (0, 2), (0, 2)), fmt(['#', '#', '#', '#'], (3, 0), (0, 0)),
    ]
    for _ in range(40):
        r, c = rng.randint(1, 9), rng.randint(1, 9)
        p = rng.choice([0.1, 0.3, 0.5, 0.7, 0.9])
        rows = [''.join('#' if rng.random() < p else '.' for _ in range(c)) for _ in range(r)]
        tests.append(fmt(rows, (rng.randrange(r), rng.randrange(c)), (rng.randrange(r), rng.randrange(c))))
    N = 500
    for p in (0.3, 0.5, 0.65):
        rows = [''.join('#' if rng.random() < p else '.' for _ in range(N)) for _ in range(N)]
        tests.append(fmt(rows, (0, 0), (N - 1, N - 1)))
    # serpentine free corridor inside a wall of seats: the free route is very long
    rows = []
    for i in range(N):
        if i % 2 == 0:
            rows.append('.' * N)
        elif (i // 2) % 2 == 0:
            rows.append('#' * (N - 1) + '.')
        else:
            rows.append('.' + '#' * (N - 1))
    tests.append(fmt(rows, (0, 0), (N - 1, 0)))
    tests.append(fmt(['#' * N] * N, (0, 0), (N - 1, N - 1)))
    return tests
